window.DATA={"meta":{"title":"La Notte senza Sole","subtitle":"Cena con delitto · Cupola City, 2077","kicker":"Cupola City · 2077","icon":"🪐","host":"vera","voices":{"n":"","v":"Vera Lux","r":"BOLT-9"},"explorePerAct":2,"ideas":["Dove eri durante i dieci minuti di buio, dalle 23:59 alle 00:10?","Cosa hai trovato esplorando? Perché non l'hai mostrato?","Chi può confermare dove eri?","Che rapporto avevi con Vera? Cosa ci perdevi, se firmava stanotte?"]},"pub":{"tony":{"name":"Tony","g":"m","img":"img/p-tony.jpg?v=1","partner":"noemi","title":"L'Ingegnere dei Robot","costume":"Camice bianco su tuta verde acqua, occhialoni cromati, cacciavite gigante","dress":"una camicia bianca o un camice, e se ce l'hai qualcosa di argentato 🤖","blurb":"Tony Rivetti ha costruito BOLT-9, il maggiordomo di Vera, e metà dei robot di Cupola City. Parla dei robot come se fossero persone. Ha un laboratorio tutto suo, al 100° piano della torre."},"noemi":{"name":"Noemi","g":"f","img":"img/p-noemi.jpg?v=1","partner":"tony","title":"La Stella dell'Olovisione","costume":"Abito corallo con le spalline spaziali, cerchietto d'argento, microfono con antenna","dress":"qualcosa di luccicante o corallo e un cerchietto tra i capelli 🎤","blurb":"Noemi Vox conduce «Indovina il Futuro», il quiz più visto della Cupola. Tutti la fermano per strada. Il canale su cui va in onda è di Vera Lux."},"laura":{"name":"Laura","g":"f","img":"img/p-laura.jpg?v=1","title":"La Chef Atomica","costume":"Giacca da chef verde acqua con bottoni cromati, cappello bianco, vassoio di pillole","dress":"un grembiule o qualcosa da chef, e un tocco di argento 👩‍🍳","blurb":"Laura Pepe è la chef più famosa della città: cene in pillole e gelato alla cometa. Il suo ristorante, «Orbita», è al 99° piano della Torre Lux da vent'anni. Stanotte la cena l'ha cucinata lei."},"alice":{"name":"Alice","g":"f","img":"img/p-alice.jpg?v=1","partner":"salvo","title":"L'Astronoma della Cupola","costume":"Cappotto blu a stelline d'argento, cannocchiale d'ottone, carta del cielo","dress":"qualcosa di blu scuro, meglio se con stelline o brillantini ✨","blurb":"Alice Stellari è l'astronoma della Cupola: ha calcolato lei la Notte delle Stelle e il passaggio della cometa. Il suo telescopio d'ottone è sulla terrazza dell'attico."},"salvo":{"name":"Salvo","g":"m","img":"img/p-salvo.jpg?v=1","partner":"alice","title":"Il Capo della Sicurezza","costume":"Divisa blu con spalline d'argento, distintivo a stella, casco a bolla sottobraccio","dress":"qualcosa di blu e, se vuoi, un distintivo (anche di carta) 🛡️","blurb":"Salvo Ferro è il capo della sicurezza della Torre Lux: tessere, ascensori, porte blindate. Niente entra o esce senza che lui lo sappia. Vera l'ha assunto cinque anni fa."}},"npc":{"vera":{"name":"Vera Lux","img":"img/n-vera.jpg?v=1","blurb":"80 anni, fondatrice della Lux Corporation: la donna che possiede il cielo. È lei che accende e spegne il Sole artificiale della Cupola. Geniale, superba, non perdona."},"bolt":{"name":"BOLT-9","img":"img/n-bolt.jpg?v=1","blurb":"Il robot maggiordomo di Vera, costruito da Tony. Serve cocktail, apre porte, ricorda tutto. Quasi tutto."}},"facts":["21:00 — Cena nel Salone delle Stelle, al 100° piano della Torre Lux. Vera: «Stanotte firmerò il nome del mio successore».","23:30 — Vera sale in Osservatorio con il suo Cocktail Nebula. BOLT-9 l'accompagna in ascensore e torna giù.","23:59 — Vera spegne il Sole dalla console. Buio su tutta la città: la cupola si apre sulle stelle.","00:10 — Si accendono le luci d'emergenza. Il Sole non torna.","00:12 — BOLT-9 sale in Osservatorio e trova Vera morta.","00:13 — Tutti salgono in Osservatorio. Salvo sorveglia la porta."],"vote":{"suspects":["tony","noemi","laura","alice","salvo","bolt"],"questions":[{"id":"killer","q":"Chi ha ucciso Vera Lux?","pts":3},{"id":"memory","q":"Chi ha spento la memoria di BOLT-9?","pts":1},{"id":"drug","q":"Chi ha messo il sonnifero nel cocktail?","pts":1},{"id":"actor","q":"Miglior attore/attrice della serata (non tu)","pts":0,"players":true}]},"topic":"nss-t0phvd5phzb6","scene":{"cena":"img/s-cena.jpg?v=1"},"p":{"3752e5477cd86a5e":"","1f3377bcbba02ff8":"","4068496a2798364b":"","c5311d1ebc25e619":"","62159c9208419993":""},"h":{"f3f3c728a0c61f9c":""},"v":1793652462555};
